type Boxart = {
    width: number; 
    height: number;
    url: string;
}

function maxBox(boxes: Boxart[]): number {
    let maxBox = 0;
    for (let i = 0; i < boxes.length; i++) {
        let curBoxSize = boxes[i].width * boxes[i].height;
        if (curBoxSize > maxBox) {
            maxBox = curBoxSize;
        }
    }
    return maxBox;
}
maxBox(boxarts); // ==> 63750
```

